import * as React from "react"

function AnimatedButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="animated-button"
      className={className}
      {...props}
    >
      <button
          className="relative border border-2 border-teal-600 rounded px-4 py-2 inline cursor-pointer text-4xl font-bold before600 hover before before0 before0  before before[4px] before before before0 before before300 before hover hover100">
          Hover me
      </button>
    </div>
  )
}

export { AnimatedButton }
